// Evidence time corrections are annotations; originals and their clocks are never rewritten.
export function validateContext(c){if(!c||typeof c.evidenceId!=='string'||typeof c.deviceId!=='string'||!['collection','import','unknown'].includes(c.timeBasis)||typeof c.observedAt!=='string'||(c.observedAt&&(!/(Z|[+-]\d{2}:\d{2})$/.test(c.observedAt)||!Number.isFinite(Date.parse(c.observedAt))))||!Number.isFinite(c.offsetMs)||Math.abs(c.offsetMs)>86400000||!Number.isFinite(c.uncertaintyMs)||c.uncertaintyMs<0||c.uncertaintyMs>86400000||typeof c.conditions!=='string'||c.conditions.length>4000||typeof c.firmwareHash!=='string'||c.firmwareHash&&!/^[a-f0-9]{64}$/i.test(c.firmwareHash))throw Error('Invalid investigation context.');return c;}
export function timeline(p,deviceId=p.deviceId){return p.evidence.filter(e=>e.deviceId===deviceId).map(e=>{const c=(p.investigationContexts||[]).find(c=>c.evidenceId===e.id);const t=c?.observedAt?Date.parse(c.observedAt)+c.offsetMs:Date.parse(e.createdAt);return {evidence:e,context:c||null,time:Number.isFinite(t)?t:null,timeBasis:c?.timeBasis||'import',earliest:c?.timeBasis==='collection'?t-c.uncertaintyMs:null,latest:c?.timeBasis==='collection'?t+c.uncertaintyMs:null};}).sort((a,b)=>(a.time??Infinity)-(b.time??Infinity));}
export function temporalRelation(a,b){if(a.earliest===null||b.earliest===null)return 'Unknown collection order';if(a.latest<b.earliest)return 'A precedes B';if(b.latest<a.earliest)return 'B precedes A';return 'Time intervals overlap; order uncertain';}
export function freezeBundle(p,{id,label,conditions,evidenceIds}){if(!label?.trim()||!Array.isArray(evidenceIds)||!evidenceIds.length)throw Error('Name the bundle and select evidence.');const entries=[...new Set(evidenceIds)].map(id=>{const e=p.evidence.find(e=>e.id===id&&e.deviceId===p.deviceId);if(!e)throw Error('Select evidence for this device.');return {evidenceId:id,title:e.title,sha256:e.hash,size:e.size,context:structuredClone((p.investigationContexts||[]).find(c=>c.evidenceId===id)||null)};});return {id,deviceId:p.deviceId,label:label.trim(),conditions:String(conditions||''),createdAt:new Date().toISOString(),entries};}
export function compareBundles(a,b){if(a.deviceId!==b.deviceId)throw Error('Choose bundles for the same device.');const rows=[];for(const title of new Set([...a.entries,...b.entries].map(e=>e.title))){const x=a.entries.filter(e=>e.title===title),y=b.entries.filter(e=>e.title===title);const detail=x.length>1||y.length>1?'Ambiguous duplicate title':!x.length?'Only in after bundle':!y.length?'Only in before bundle':x[0].sha256===y[0].sha256?'Same bytes':'Changed bytes';rows.push({title,detail});}return {conditionsMatch:a.conditions===b.conditions,rows,limitation:'Bundle membership is a selection, not proof of presence, removal or remediation on the target.'};}
export function validateInvestigation(p){for(const k of ['investigationContexts','investigationBundles']){p[k]??=[];if(!Array.isArray(p[k])||p[k].length>1000)throw Error('Invalid investigation collection.');}const seen=new Set();for(const c of p.investigationContexts){validateContext(c);if(seen.has(c.evidenceId)||!p.evidence.some(e=>e.id===c.evidenceId&&e.deviceId===c.deviceId))throw Error('Broken or duplicate investigation context.');seen.add(c.evidenceId);}const ids=new Set();for(const b of p.investigationBundles){if(!b||typeof b.id!=='string'||ids.has(b.id)||typeof b.label!=='string'||typeof b.conditions!=='string'||!Array.isArray(b.entries)||!b.entries.length||b.entries.length>20000)throw Error('Invalid bundle.');ids.add(b.id);const refs=new Set();for(const x of b.entries){const e=p.evidence.find(e=>e.id===x.evidenceId&&e.deviceId===b.deviceId);if(!e||refs.has(e.id)||e.hash!==x.sha256||e.size!==x.size||typeof x.title!=='string')throw Error('Bundle original missing or altered.');refs.add(e.id);if(x.context){validateContext(x.context);if(x.context.evidenceId!==e.id||x.context.deviceId!==e.deviceId)throw Error('Mismatched frozen context.');}}}return p;}
